# Building

## The spine and its look

Build the opening, one middle chapter and the ending in two or three looks.
Let the person scroll those looks, ask which they choose, and stop for their
answer before building the remaining chapters. An unanswered question in
this turn is not a refusal to choose or permission to choose for them.

## The chapters and their words

After the look choice, build the remaining chapters. For the opening and
closing wording, show three versions of each whole beat, including the
surrounding fixed text. Recommend one and leave room for their own wording.
Stop for the choice, then use it word for word.

## The scene

Compare the running scene with the storyboard at its settled beats. With the captions hidden, does each scene show what the storyboard says it shows, rather than only names for it? Revise the composition when the explanation lives only in the surrounding prose. Keep that accessible prose; it does not replace what the scene was meant to show.

Inspect the changes between beats in both scroll directions, including intermediate positions. When words in the scene change, correct any overlap that makes the old and new words unreadable together. A readable settled beat does not establish a readable transition.

Read every word in the scene at the size it is shown on a desktop, a phone and a short screen. Words too small to read there go to the caption.
"use client";
import { useRef } from "react";
import { useFrame } from "@react-three/fiber";
import type { Group } from "three";
import type { PieceProps } from "@/components/story/types";
import { Block, Leaf, Stroke } from "./geometry";
export function Runbook({ look, frameRef, still }: PieceProps) {
  const root=useRef<Group>(null), left=useRef<Group>(null);
  useFrame(()=>{
    const f=frameRef.current;
    const end=f.beat>2 ? Math.min(1,(f.beat-2)*.9+(f.from===3?f.dwell*.1:0)) : 0;
    const opening=f.from===0&&f.to===0 ? (still?1:f.dwell) : 1;
    const closing=still?(f.from===3?1:0):end;
    if(left.current) left.current.rotation.z = -Math.PI*closing - (1-opening)*1.25;
    if(root.current) root.current.position.x=-1.12*closing;
  });
  const cover=look.id==="dark"?"#34463d":"#b34e2c";
  return <group ref={root} position={[0,-.3,0]}>
    <group ref={left} position={[0,.03,0]}>
      <Block position={[-1.15,-.12,0]} size={[2.3,.12,3.17]} color={cover} />
      {[0,1,2,3].map(i=><group key={i} position={[-1.1,i*.028,0]}><Leaf color={look.surface.color} curl={.06+i*.025}/></group>)}
    </group>
    <Block position={[1.15,-.09,0]} size={[2.3,.12,3.17]} color={cover} />
    {[0,1,2,3].map(i=><group key={i} position={[1.1,i*.028,0]}><Leaf color={look.surface.color} curl={.15-i*.028}/></group>)}
    <Stroke from={[0,.12,-1.5]} to={[0,.12,1.5]} color={cover} radius={.035}/>
    <Block position={[.15,-.04,1.78]} size={[.16,.025,.7]} color={look.accent}/>
  </group>;
}
"use client";
import { useEffect, useMemo } from "react";
import { BoxGeometry, DoubleSide, Quaternion, Vector3 } from "three";
export type V3 = [number, number, number];
export function Block({ position = [0,0,0], size = [1,1,1], color = "#495b50", rotation = [0,0,0] }: { position?: V3; size?: V3; color?: string; rotation?: V3 }) {
  return <mesh position={position} rotation={rotation} castShadow receiveShadow><boxGeometry args={size} /><meshStandardMaterial color={color} roughness={.92} /></mesh>;
}
export function Stroke({ from, to, color = "#9d532f", radius = .015 }: { from: V3; to: V3; color?: string; radius?: number }) {
  const a=new Vector3(...from), b=new Vector3(...to), d=b.clone().sub(a);
  return <mesh position={a.add(b).multiplyScalar(.5)} quaternion={new Quaternion().setFromUnitVectors(new Vector3(0,1,0), d.clone().normalize())} castShadow><cylinderGeometry args={[radius,radius,d.length(),8]} /><meshStandardMaterial color={color} roughness={.9} /></mesh>;
}
export function Leaf({ color, curl = .09 }: { color: string; curl?: number }) {
  const geometry = useMemo(() => {
    const g = new BoxGeometry(2.15,.018,2.95,24,1,12), p=g.attributes.position;
    for(let i=0;i<p.count;i++) p.setY(i,p.getY(i)+curl*Math.sin((p.getX(i)/2.15+.5)*Math.PI));
    g.computeVertexNormals();return g;
  },[curl]);
  useEffect(()=>()=>geometry.dispose(),[geometry]);
  return <mesh geometry={geometry} castShadow receiveShadow><meshStandardMaterial color={color} side={DoubleSide} roughness={.92} /></mesh>;
}
export function Catalogue({ accent }: { accent: string }) {
  return <group position={[0,.04,-.45]}>
    <Block position={[0,.65,0]} size={[2.25,1.3,.78]} color="#ae9370" />
    {[-.74,0,.74].flatMap(x=>[0,1,2].map(row=><group key={`${x}-${row}`} position={[x,.24+row*.4,.415]}>
      <Block size={[.66,.32,.04]} color="#e0cfaa" /><Block position={[0,-.01,.045]} size={[.19,.055,.04]} color="#34443c" />
    </group>))}
    <Block position={[1.4,.5,-.1]} size={[.15,.92,.65]} color={accent} rotation={[0,0,-.15]} />
    <Block position={[-1.4,.43,-.1]} size={[.16,.8,.65]} color="#657866" rotation={[0,0,.13]} />
  </group>;
}
